import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class DefaultBoxAndWhiskerCategoryDataset_add_TriageGen1Test {

    private DefaultBoxAndWhiskerCategoryDataset dataset;

    @Before
    public void setUp() {
        dataset = new DefaultBoxAndWhiskerCategoryDataset();
    }

    @Test
    public void testAddFirstItemSetsBounds() {
        BoxAndWhiskerItem item = new BoxAndWhiskerItem(null, null, null, null, null, 10.0, 20.0);
        // Note: Based on code, it uses item.getMinOutlier() and item.getMaxOutlier() for range calculation
        // We need to mock or provide an item where these return values.
        // Assuming BoxAndWhiskerItem constructor or setters allow setting outliers.

        BoxAndWhiskerItem item1 = createItem(5.0, 15.0);
        dataset.add(item1, "Row1", "Col1");

        assertEquals(5.0, dataset.getRangeLowerBound(true), 0.001);
        assertEquals(15.0, dataset.getRangeUpperBound(true), 0.001);
    }

    @Test
    public void testAddItemUpdatesMaxBound() {
        dataset.add(createItem(5.0, 15.0), "R1", "C1");
        dataset.add(createItem(6.0, 25.0), "R1", "C2");

        assertEquals(5.0, dataset.getRangeLowerBound(true), 0.001);
        assertEquals(25.0, dataset.getRangeUpperBound(true), 0.001);
    }

    @Test
    public void testAddItemUpdatesMinBound() {
        dataset.add(createItem(5.0, 15.0), "R1", "C1");
        dataset.add(createItem(2.0, 12.0), "R1", "C2");

        assertEquals(2.0, dataset.getRangeLowerBound(true), 0.001);
        assertEquals(15.0, dataset.getRangeUpperBound(true), 0.001);
    }

    @Test
    public void testAddWithNullOutliers() {
        // item.getMinOutlier() returns null -> minval = NaN
        BoxAndWhiskerItem item = createItem(null, null);
        dataset.add(item, "R1", "C1");

        // If both are NaN, max/min range values will be NaN
        // Depending on implementation of Range, this might be tricky, 
        // but we follow the logic: if NaN, maxval is NaN.
        // If maxval is NaN, it doesn't trigger the 'else if (maxval > this.maximumRangeValue)'
        // So the bounds remain NaN.
        assertEquals(Double.NaN, dataset.getRangeLowerBound(true), 0.0);
        assertEquals(Double.NaN, dataset.getRangeUpperBound(true), 0.0);
    }

    @Test
    public void testUpdateBoundsTriggered() {
        // To trigger updateBounds(), the new item must be at the same (row, col) 
        // as the current maximum or minimum range value.

        dataset.add(createItem(10.0, 20.0), "R1", "C1");

        // Current max is at (0, 0) [assuming indices]. 
        // Adding another item to the same cell with different values should trigger updateBounds via the if condition
        // even if it doesn't change the actual max/min value.
        dataset.add(createItem(5.0, 25.0), "R1", "C1");

        assertEquals(5.0, dataset.getRangeLowerBound(true), 0.001);
        assertEquals(25.0, dataset.getRangeUpperBound(true), 0.001);
    }

    @Test
    public void testAddLargeValues() {
        dataset.add(createItem(Double.NEGATIVE_INFINITY, Double.MAX_VALUE), "R1", "C1");
        assertEquals(Double.NEGATIVE_INFINITY, dataset.getRangeLowerBound(true), 0.0);
        assertEquals(Double.MAX_VALUE, dataset.getRangeUpperBound(true), 0.0);
    }

    /**
     * Helper to create BoxAndWhiskerItem. 
     * Since I don't have the BoxAndWhiskerItem source, I assume a standard constructor 
     * or that we can manipulate it via a mock/subclass if necessary.
     * Given the target code uses getMinOutlier() and getMaxOutlier().
     */
    private BoxAndWhiskerItem createItem(Double minOutlier, Double maxOutlier) {
        // This is a placeholder. In a real scenario, use the actual constructor.
        // For this test, we assume BoxAndWhiskerItem can be instantiated this way.
        BoxAndWhiskerItem item = new BoxAndWhiskerItem(null, null, null, null, null, null, null);
        // We use reflection or assume setters exist to satisfy the requirement of the 'add' method logic
        try {
            java.lang.reflect.Field minField = BoxAndWhiskerItem.class.getDeclaredField("minOutlier");
            minField.setAccessible(true);
            if (minOutlier != null) minField.set(item, minOutlier);

            java.lang.reflect.Field maxField = BoxAndWhiskerItem.class.getDeclaredField("maxOutlier");
            maxField.setAccessible(true);
            if (maxOutlier != null) maxField.set(item, maxOutlier);
        } catch (Exception e) {
            // If reflection fails, this test environment isn't set up for it, 
            // but this is the standard way to force specific branch coverage for internal fields.
        }
        return item;
    }
}
